(function(){
'use strict';
const D=window.PROJECT_DATA,G=window.PresentationCharts;
if(!D||!G)return;
const slides=[...document.querySelectorAll('.slide')],charts=new Map();
const state={index:0,feature:'rms',compare:false,model:'E4',grain:'raw_window',reducedMotion:window.matchMedia('(prefers-reduced-motion: reduce)').matches,narrow:window.innerWidth<700};
const $=id=>document.getElementById(id),pct=x=>G.number(x*100)+' %',signed=x=>(x<0?'−':'+')+G.number(Math.abs(x)*100)+' points';
const row=(stage,experiment)=>D.summary.find(r=>r.stage===stage&&r.experiment===experiment);
const final=row('final','E4'),dev=row('development','E4'),diff=D.bootstrap.comparisons.E4_minus_E1;
const values={'final-e4':pct(final.balanced_accuracy),'final-e1':pct(row('final','E1').balanced_accuracy),'dev-e4':pct(dev.balanced_accuracy),'dev-gain':signed(dev.balanced_accuracy-row('development','E3').balanced_accuracy),'dev-tree-delta':signed(row('development','E2').balanced_accuracy-row('development','E1').balanced_accuracy),'final-gain':signed(diff.point_difference),'baseline-ci':`[${G.number(diff.ci95[0]*100)} ; ${G.number(diff.ci95[1]*100)}]`};
for(const [key,value]of Object.entries(values))document.querySelectorAll(`[data-value="${key}"]`).forEach(n=>n.textContent=value);
const notes=[
['35 s. Présenter les quatre états. Le modèle E4 a été retenu avant le test. Le score affiché donne le même poids à chaque enregistrement. Il ne prouve pas un transfert industriel.','results/summary.csv, results/selection.json'],
['60 s. Un essai sain et trois essais de chaque défaut par charge. Les plis GroupKFold valident chacun une charge entière parmi 0, 1 et 2 HP. Le sain est à 48 kHz. Deux vitesses saines sont approximatives et tracées.','data/manifest.csv, data/classcoverage.csv, data/splits/recordings.csv'],
['55 s. Le signal est centré par fenêtre. RMS mesure l’amplitude efficace. La kurtosis de Pearson, corrigée du biais, a une référence gaussienne de 3. Le facteur de crête est max|x| / RMS. Le trait court indique la médiane de la classe.','docs/features.md, sorties de caractéristiques du développement'],
['70 s. Les deux exemples viennent du développement. BPFO et BPFI dépendent du roulement et de la vitesse. Les trois premières harmoniques sont intégrées dans ±3 Hz pour toutes les classes. La bande fixe n’est pas proclamée optimale. Les axes d’amplitude sont indépendants.','docs/features.md, CWRU bearing information, IR007_0 et OR007@6_0'],
['55 s. Le FIR commun limite le confondant de préparation entre 12 et 48 kHz. Les transitoires écartés totalisent 0,2 s. Une fenêtre brute dure 1 s. L’enveloppe garde 0,9 s après coupe des bords. Hilbert utilise la fenêtre complète.','configs/experiment.json, results/filter_diagnostics.json'],
['55 s. Comparer E2 avec E1 et E4 avec E3 pour les entrées. Comparer E3 avec E1 et E4 avec E2 pour le classifieur. Les dix colonnes ajoutées comprennent quatre formes spectrales et six énergies d’harmoniques.','results/feature_dictionary.csv, results/selection.json'],
['75 s. E4 donne le meilleur score de développement. Les nouvelles entrées améliorent la forêt et dégradent l’arbre. Ces scores ont servi au réglage et à la sélection : ils sont optimistes et ne sont pas une estimation indépendante.','results/development_metrics.json, results/selection.json'],
['80 s. Une seule campagne finale E1–E4 suit le gel. E2 et E4 ont le même score final. E3 est inférieur à E1. Le choix reste celui du développement. La comparaison des deux populations n’isole pas un effet causal de la charge.','results/final_metrics.json, results/final_bootstrap.json, results/test_consulted.json'],
['65 s. La matrice brute et le rappel pondéré ont des dénominateurs différents. E4 fait deux erreurs de fenêtre, toutes deux sur la bague externe. L’agrégation moyenne les probabilités par enregistrement. Changer le modèle affiché ne modifie pas le modèle sélectionné.','results/final_metrics.json, docs/protocol.md'],
['50 s. Le bootstrap rééchantillonne les enregistrements par classe de manière appariée entre modèles. L’intervalle E4 − E1 touche zéro. Un seul essai sain ne mesure aucune variabilité entre essais de cette classe. Les roulements physiques peuvent être liés entre charges.','results/final_bootstrap.json, docs/data_audit.md']
];
function table(id,headers,rows){const wrap=$(id);wrap.replaceChildren();const t=document.createElement('table');t.className='data-table';const thead=document.createElement('thead'),tr=document.createElement('tr');headers.forEach(h=>{const th=document.createElement('th');th.scope='col';th.textContent=h;tr.append(th);});thead.append(tr);t.append(thead);const body=document.createElement('tbody');rows.forEach(row=>{const tr=document.createElement('tr');row.forEach((v,i)=>{const cell=document.createElement(i===0?'th':'td');if(i===0)cell.scope='row';cell.textContent=v;tr.append(cell);});body.append(tr);});t.append(body);wrap.append(t);}
table('coverage-table',['Classe','0 HP','1 HP','2 HP','3 HP (test)'],G.CLASSES.map((c,i)=>[G.LABELS[i],...[0,1,2,3].map(hp=>D.coverage.find(r=>r.class_label===c&&r.load_hp===hp).n_recordings)]));
const featureInfo={rms:['Amplitude efficace, unité source non certifiée','RMS'],kurtosis:['Kurtosis de Pearson, référence gaussienne : 3','Kurtosis'],crest_factor:['Rapport du pic à RMS, sans unité','Facteur de crête']};
function updateTemporal(){document.querySelectorAll('[data-feature]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.feature===state.feature)));$('feature-definition').textContent=featureInfo[state.feature][0]+' · trait court : médiane de classe';table('temporal-table',['Enregistrement','Classe',featureInfo[state.feature][1]],D.temporal.map(r=>[r.recording_id,G.LABELS[G.CLASSES.indexOf(r.class_label)],G.number(r[state.feature],5)]));render('temporal-chart');}
function updateConfusion(){const m=D.metrics[state.model],stats=m[state.grain],cm=stats.confusion;const n=cm.flat().reduce((a,b)=>a+b,0),correct=cm.reduce((a,row,i)=>a+row[i],0),errors=n-correct;const unit=state.grain==='record'?'essais':'fenêtres';$('error-headline').textContent=errors===0?'aucune erreur après agrégation.':`${errors} erreur${errors>1?'s':''} sur ${n} ${unit}.`;$('confusion-caption').textContent=`${state.model} · ${n} ${unit} · comptes bruts`;$('record-score').textContent=`${Math.round(m.record.accuracy*m.n_recordings)}/${m.n_recordings}`;$('outer-recall').textContent=pct((state.grain==='record'?m.record:m.weighted_window).recall_by_class.outer_race);$('outer-recall-label').textContent=state.grain==='record'?'Rappel externe par essai':'Rappel externe pondéré par essai';document.querySelectorAll('[data-grain]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.grain===state.grain)));table('confusion-table',['Réel / prédit',...G.LABELS],cm.map((r,i)=>[G.LABELS[i],...r]));$('confusion-chart').setAttribute('aria-label',`${state.model}, ${errors} erreurs sur ${n} ${unit}. Lignes réelles, colonnes prédites. Tableau exact disponible juste après le graphique.`);render('confusion-chart');}
table('uncertainty-table',['Comparaison','Gain (points)','IC 95 % (points)'],['E4_minus_E1','E4_minus_E3','E4_minus_E2'].map(k=>{const r=D.bootstrap.comparisons[k];return [k.replace('_minus_',' − '),G.number(r.point_difference*100),`[${G.number(r.ci95[0]*100)} ; ${G.number(r.ci95[1]*100)}]`];}));
function render(id){const node=$(id);if(!node||node.closest('.slide').hidden)return;if(!window.echarts){node.textContent='Le moteur graphique n’a pas pu être chargé. Les résultats exacts restent dans les tableaux et le dépôt.';node.classList.add('chart-error');return;}try{let chart=charts.get(id);if(!chart){chart=echarts.init(node,null,{renderer:'svg'});charts.set(id,chart);}chart.setOption(G.buildOptions(id,D,state),true);chart.resize();}catch(error){node.textContent='Ce graphique est indisponible. Consultez les valeurs exactes dans le tableau ou les sources.';node.classList.add('chart-error');console.error(error);}}
function updateNotes(){$('notes-content').textContent=notes[state.index][0];$('notes-source').textContent='Sources : '+notes[state.index][1];}
function show(index,{hash=true,focus=false}={}){state.index=Math.max(0,Math.min(slides.length-1,index));slides.forEach((s,i)=>s.hidden=i!==state.index);$('slide-number').textContent=String(state.index+1).padStart(2,'0');$('previous-button').disabled=state.index===0;$('next-button').disabled=state.index===slides.length-1;document.querySelectorAll('[data-slide]').forEach(b=>{if(Number(b.dataset.slide)===state.index)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');b.classList.toggle('completed',Number(b.dataset.slide)<state.index);});updateNotes();if(hash)history.replaceState(null,'',`#${state.index+1}`);document.title=`${state.index+1}/10 · ${slides[state.index].dataset.title} — CWRU Lab`;for(const node of slides[state.index].querySelectorAll('.chart'))render(node.id);if(focus){const heading=slides[state.index].querySelector('h1,h2');heading.tabIndex=-1;heading.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});}
slides.forEach((s,i)=>{const progress=document.createElement('button');progress.dataset.slide=i;progress.setAttribute('aria-label',`Diapositive ${i+1} : ${s.dataset.title}`);progress.addEventListener('click',()=>show(i,{focus:true}));$('slide-progress').append(progress);const plan=document.createElement('button');plan.dataset.slide=i;const num=document.createElement('span');num.textContent=String(i+1).padStart(2,'0');plan.append(num,document.createTextNode(s.dataset.title));plan.addEventListener('click',()=>{$('plan-dialog').close();show(i,{focus:true});});$('plan-links').append(plan);});
$('previous-button').addEventListener('click',()=>show(state.index-1));$('next-button').addEventListener('click',()=>show(state.index+1));
function openDialog(id){$(id).showModal();}
$('plan-button').addEventListener('click',()=>openDialog('plan-dialog'));$('sources-button').addEventListener('click',()=>openDialog('sources-dialog'));document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>$(b.dataset.close).close()));
function toggleNotes(){const hidden=!$('notes-panel').hidden;$('notes-panel').hidden=hidden;$('notes-button').setAttribute('aria-pressed',String(!hidden));}
$('notes-button').addEventListener('click',toggleNotes);$('close-notes').addEventListener('click',toggleNotes);
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{$('fullscreen-button').textContent='Utilisez F11';}}
$('fullscreen-button').addEventListener('click',fullscreen);document.addEventListener('fullscreenchange',()=>{$('fullscreen-button').textContent=document.fullscreenElement?'Quitter le plein écran':'Plein écran';resize();});
document.querySelectorAll('[data-feature]').forEach(b=>b.addEventListener('click',()=>{state.feature=b.dataset.feature;updateTemporal();}));
$('compare-development').addEventListener('change',e=>{state.compare=e.target.checked;$('transfer-scope').textContent=state.compare?'Comparaison de populations : 30 essais de développement et 10 essais finaux. Même métrique pondérée.':'Test réservé à 3 HP. 10 essais, 92 fenêtres. Poids égal par enregistrement.';$('transfer-note').textContent=state.compare?'Les scores de développement ont servi à la sélection et sont optimistes. Cette comparaison n’isole pas un effet causal de la charge.':'Une seule campagne finale après gel. Un seul essai sain au test final.';render('transfer-chart');});
$('confusion-model').addEventListener('change',e=>{state.model=e.target.value;updateConfusion();});document.querySelectorAll('[data-grain]').forEach(b=>b.addEventListener('click',()=>{state.grain=b.dataset.grain;updateConfusion();}));
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.altKey||e.metaKey||e.target.closest('input,select,textarea,[contenteditable=true]'))return;if(document.querySelector('dialog[open]'))return;const key=e.key.toLowerCase();if(['arrowright','pagedown'].includes(key)||(key===' '&&e.target===document.body)){e.preventDefault();show(state.index+1);}else if(['arrowleft','pageup'].includes(key)){e.preventDefault();show(state.index-1);}else if(key==='home'){e.preventDefault();show(0);}else if(key==='end'){e.preventDefault();show(9);}else if(key==='p')openDialog('plan-dialog');else if(key==='n')toggleNotes();else if(key==='f')fullscreen();});
window.addEventListener('hashchange',()=>{const n=Number(location.hash.slice(1));if(Number.isInteger(n)&&n>=1&&n<=10)show(n-1,{hash:false});});
function resize(){state.narrow=window.innerWidth<700;for(const node of slides[state.index].querySelectorAll('.chart'))render(node.id);}let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(resize,120);});
updateTemporal();updateConfusion();const initial=Number(location.hash.slice(1));show(Number.isInteger(initial)&&initial>=1&&initial<=10?initial-1:0);if(document.fonts)document.fonts.ready.then(resize);
})();
